import sys

def is_t_prime(n):
    """Check if a number is T-prime."""
    if n < 4:
        return False
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

