import sys
import math
def sieve(max_val=1000000):
    primes = bytearray([1]) * (max_val + 1)
    primes[0] = primes[1] = 0
    for i in range(2, int(max_val**0.5) + 1):
        if primes[i]:
            primes[i*i:max_val+1:i] = bytearray([0]) * len(range(i*i, max_val+1, i))
    return primes
def solve():
    lines = sys.stdin.read().splitlines()
    if not lines: return
    n = int(lines[0])
    nums = list(map(int, lines[1].split()))
    is_prime = sieve(1000000)
    for x in nums:
        r = int(math.isqrt(x))
        if r * r == x and is_prime[r]:
            print('YES')
        else:
            print('NO')
if __name__ == '__main__':
    solve()
